struct ContentView: View {
    @State private var name = ""
    @State private var count = 0

    var body: some View {
        VStack {
            TextField("Enter your name", text: $name)
                .padding()
                .background(Color.gray.opacity(0.2))
                .cornerRadius(8)
            Button(action: {
                self.count += 1
            }) {
                Text("Tap me")
                    .padding()
                    .background(Color.blue)
                    .foregroundColor(.white)
                    .cornerRadius(8)
            }
            Text("Hello, \(name)!")
            Text("Count: \(count)")
        }
    }
}
```

### Step 5: Add navigation

Let's add a navigation bar to our app. We can use the `NavigationView` to create a navigation bar.

```swift
